/*
    Butter-Smooth Morph Among N, E, and O via
    SDF "Shell Expansion" + Smooth Union

    How it works:
    1) dA is shape A's SDF, dB is shape B's SDF.
    2) We add an offset to each shape:
         dA' = dA + (t * fadeOutOffset)
         dB' = dB + ((1-t) * fadeInOffset)
       - As t goes from 0 to 1:
         * A is pushed outward (becomes more positive) => disappears
         * B is pulled inward (becomes less positive)  => appears
    3) We combine them with a smooth union, so they
       gently merge in the mid-states rather than snap or flicker.

    By adjusting the offsets and smoothing factor,
    you can often find a sweet spot where the morph
    is quite natural & artifact-free.
*/

#ifdef GL_ES
precision mediump float;
#endif

//-----------------------------------------------------
// Distance / SDF Utilities
//-----------------------------------------------------

// Distance from point p to line segment (a->b).
float lineSegmentDist(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a;
    vec2 ba = b - a;
    float t = clamp(dot(pa, ba)/dot(ba, ba), 0.0, 1.0);
    return length(pa - ba*t);
}

// Stroke SDF for a line segment.
float lineSegmentSDF(vec2 p, vec2 a, vec2 b, float halfWidth)
{
    return lineSegmentDist(p, a, b) - halfWidth;
}

// Ring SDF: negative inside ring stroke, positive outside.
float ringSDF(vec2 p, float radius, float halfThickness)
{
    float d = length(p) - radius;
    return abs(d) - halfThickness;
}

// Smooth union of two distances, controlling how softly they merge.
float opSmoothUnion(float d1, float d2, float k)
{
    // Larger k => softer merging region
    float h = clamp(0.5 + 0.5*(d2 - d1)/k, 0.0, 1.0);
    return mix(d2, d1, h) - k*h*(1.0 - h);
}

//-----------------------------------------------------
// Letters (N, E, O) SDF
// Each letter is about ~[-0.15..+0.15] wide and ~[-0.25..+0.25] tall
//-----------------------------------------------------

float letterN(vec2 p)
{
    float dLeft  = lineSegmentSDF(p, vec2(-0.15,-0.25), vec2(-0.15, 0.25), 0.02);
    float dRight = lineSegmentSDF(p, vec2( 0.15,-0.25), vec2( 0.15, 0.25), 0.02);
    float dDiag  = lineSegmentSDF(p, vec2(-0.15,-0.25), vec2( 0.15, 0.25), 0.02);
    return min(dLeft, min(dRight, dDiag));
}

float letterE(vec2 p)
{
    float dVert = lineSegmentSDF(p, vec2(-0.15,-0.25), vec2(-0.15, 0.25), 0.02);
    float dTop  = lineSegmentSDF(p, vec2(-0.15, 0.25), vec2( 0.15, 0.25), 0.02);
    float dMid  = lineSegmentSDF(p, vec2(-0.15, 0.00), vec2( 0.10, 0.00), 0.02);
    float dBot  = lineSegmentSDF(p, vec2(-0.15,-0.25), vec2( 0.15,-0.25), 0.02);
    return min(dVert, min(dTop, min(dMid, dBot)));
}

float letterO(vec2 p)
{
    // O: ring with radius=0.20, thickness=0.04
    return ringSDF(p, 0.20, 0.02);
}

// Master letter function: 0->N, 1->E, 2->O
float letterSDF(vec2 p, int index)
{
    if(index == 0) return letterN(p);
    if(index == 1) return letterE(p);
    return letterO(p);
}

//-----------------------------------------------------
// Shell-Expansion Morph
//-----------------------------------------------------
/*
  shapeMorph(dA, dB, t) 
   - dA => letter A's SDF
   - dB => letter B's SDF
   - t in [0..1]

  We define two offsets:
    outA = t*fadeOutOffset
    inB  = (1.0 - t)*fadeInOffset

  So:
    dA' = dA + outA
    dB' = dB + inB

  Then we combine with a smooth union. A is "pushed outward"
  over time => disappears. B is "pulled inward" => appears.
  Because it's a union, the shape never has holes or lumps
  in the middle (assuming a big enough smoothing factor).
*/
float shapeMorph(float dA, float dB, float t)
{
    // You can tweak these for different feels
    float fadeOutOffset = 1.0; // how far we push shape A out
    float fadeInOffset  = 1.0; // how far we pull shape B in
    float kSmooth       = 0.07; // smoothing parameter

    float dA_ = dA + t*fadeOutOffset;       // push A outward
    float dB_ = dB + (1.0 - t)*fadeInOffset; // pull B inward

    return opSmoothUnion(dA_, dB_, kSmooth);
}

//-----------------------------------------------------
// MAIN
//-----------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized coords in [-1..+1], fix aspect
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;

    // 3-second loop
    float T = 3.0;
    float t = mod(iTime, T);
    int   iCur  = int(floor(t));      // current letter
    int   iNext = (iCur + 1) % 3;     // next letter
    float f     = fract(t);          // 0..1

    // SDF for current and next letters
    float dA = letterSDF(uv, iCur);
    float dB = letterSDF(uv, iNext);

    // Shell expansion morph
    float d = shapeMorph(dA, dB, f);

    // Distance-based coloring (inspired by Inigo Quilez)
    vec3 colInside  = vec3(0.65, 0.85, 1.0); 
    vec3 colOutside = vec3(0.9,  0.6,  0.3); 
    vec3 baseCol    = (d > 0.0) ? colOutside : colInside;

    // "Fog out" far from boundary
    baseCol *= 1.0 - exp(-6.0 * abs(d));

    // Subtle wave effect
    baseCol *= 0.8 + 0.2 * cos(120.0 * d);

    // Bright highlight near boundary
    baseCol = mix(baseCol, vec3(1.0), 1.0 - smoothstep(0.0, 0.01, abs(d)));

    fragColor = vec4(baseCol, 1.0);
}
